import json
import os
import urllib
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import padding

remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}

password = (cfg.get('password') or '').strip()
auth_account = (cfg.get('user') or '').strip()
auth_pass_b64 = (cfg.get('authPass') or '').strip()

if not password or password.strip() == '':
    raise Exception("Missing environment variable 'password' in connection_params")

if not auth_account or auth_account.strip() == '':
    raise Exception("Missing environment variable 'user' in connection_params")

if not auth_pass_b64 or auth_pass_b64.strip() == '':
    raise Exception("Missing environment variable 'authPass' in connection_params")

try:
    iv = os.urandom(16)
    key = base64.b64decode(auth_pass_b64)
    if not key or len(key) == 0:
        raise Exception('Failed to parse authPass as Base64 key')
    backend = default_backend()
    cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=backend)
    encryptor = cipher.encryptor()
    padder = padding.PKCS7(128).padder()
    padded_data = padder.update(password.encode('utf-8')) + padder.finalize()
    encrypted = encryptor.update(padded_data) + encryptor.finalize()
    if not encrypted:
        raise Exception('Encryption failed - no ciphertext generated')
    iv_b64 = base64.b64encode(iv)
    encrypted_b64 = base64.b64encode(encrypted)
    if not iv_b64 or not encrypted_b64:
        raise Exception('Base64 encoding failed')
    final_encrypted = iv_b64 + encrypted_b64
    try:
        encrypted_password = urllib.quote(final_encrypted, safe='')
    except AttributeError:
        raise Exception('Encryption error: %s' % str(encryption_error))

except Exception as encryption_error:
    raise Exception('Encryption error: %s' % str(encryption_error))

try:
    encoded_user = urllib.quote(auth_account, safe='')
except AttributeError:
    raise Exception('Encryption error: %s' % str(encryption_error))

base = (base_url or '').rstrip('/')

auth_url = '%s/accounts/%s?authentication=%s' % (
    base,
    auth_account,
    encrypted_password
)
resp = request_retry('GET', auth_url)

if resp.status_code >= 400:
    # Log detailed error
    error_msg = "Token request failed: %s %s" % (resp.status_code, resp.text)
    raise Exception(error_msg)

token = (resp.text or '').strip()
if not token:
    raise Exception("Empty token received from server")
bag['token'] = token
bag['auth_response'] = {'token': token, 'user': auth_account}

import json
from datetime import timedelta

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()
condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(condition)
sensor_ids = [s.id for s in sensors]

last_readings_map = {}
if sensors:
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for sid, mtime in cr.fetchall():
        last_readings_map[sid] = mtime

plan = []
for sensor in sensors:
    device = sensor.device_id

    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}

    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

    station_id = device_cfg.get('station_id')
    if station_id is not None:
        station_id = str(station_id).strip()
    else:
        station_id = ''

    channel_id = sensor_cfg.get('channel_id')
    if channel_id is not None:
        channel_id = str(channel_id).strip()
    else:
        channel_id = ''

    if not station_id or channel_id == '':
        continue

    last_reading = last_readings_map.get(sensor.id)

    if last_reading:
        start_date = str(last_reading)
    else:
        start_cfg = sensor_cfg.get('start_date') or device_cfg.get('start_date')
        if start_cfg:
            start_date = start_cfg
        else:
            year = today_str[:4]
            start_date = '%s-01-01' % year

    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'station_id': station_id,
        'channel_id': channel_id,
        'start_date': start_date,
        'sensor_name': sensor.name or '',
        'device_name': device.name or '',
    })

bag['sensors_plan'] = plan
bag['sensors_plan_count'] = len(plan)
